export const COURSE_MAP: Record<string, Course> = Object.fromEntries(COURSES.map((c) => [c.slug, c]));

export function courseTopicCount(course: Course) {
  return course.topics.reduce((a, t) => a + t.subtopics.length, 0);
}

export const DIFFICULTIES: Difficulty[] = ["beginner", "intermediate", "advanced", "interview"];

export const DIFFICULTY_LABEL: Record<Difficulty, string> = {
  beginner: "Beginner",
  intermediate: "Intermediate",
  advanced: "Advanced",
  interview: "Interview Prep",
};

export const IMPORTANCE_LABEL: Record<Importance, string> = {
  critical: "Critical for interviews",
  high: "High priority",
  medium: "Good to have",
};
